 reports=json.loads((O/'summary.json').read_text());e0=json.loads((O/'E0.json').read_text());diag=json.loads((P/'llama_diagnostic_final/summary.json').read_text());(O/'llama_diagnostic.json').write_text(json.dumps(diag,indent=2))
